def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    bars = components(g == 5)
    pats = components((g != bg) & (g != 5))
    H, W = g.shape
    for bar in bars:
        bset = set(bar)
        by0, bx0, by1, bx1 = bbox(bar)
        horizontal = (by0 == by1) and (bx1 > bx0)
        for p in pats:
            touches = any((y + dy, x + dx) in bset for (y, x) in p
                          for dy in (-1, 0, 1) for dx in (-1, 0, 1))
            if not touches:
                continue
            py0, px0, py1, px1 = bbox(p)
            pat = g[py0:py1 + 1, px0:px1 + 1]
            ph, pw = pat.shape
            if horizontal:
                for y in range(py0, py1 + 1):
                    for x in range(bx0, bx1 + 1):
                        out[y, x] = pat[y - py0, (x - px0) % pw]
                emit(out, f"Repeat the patch at rows {py0}-{py1} along the horizontal bar across columns {bx0}-{bx1}.")
            else:
                for y in range(by0, by1 + 1):
                    for x in range(px0, px1 + 1):
                        out[y, x] = pat[(y - py0) % ph, x - px0]
                emit(out, f"Tile the patch at columns {px0}-{px1} along the vertical bar across rows {by0}-{by1}.")
    emit(out, "Final grid: every patch extended along its bar.")
    return out
